            gifImageView = new ImageView();
            gifImageView.setFitWidth(400);
            gifImageView.setFitHeight(240);
            gifImageView.setPreserveRatio(true);

            explanationImageView = new ImageView();
            explanationImageView.setFitWidth(360);
            explanationImageView.setFitHeight(140);
            explanationImageView.setPreserveRatio(true);

            instructionLabel = new Label("Perhatikan gerakan teknik ini dengan seksama");
            instructionLabel.setStyle(
                    "-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-text-fill: #1A1E2C; -fx-text-alignment: center;");
            instructionLabel.setWrapText(true);
            instructionLabel.setMaxWidth(580);
            instructionLabel.setAlignment(Pos.CENTER);
            instructionLabel.setMaxHeight(60);

            whiteBox.getChildren().addAll(gifImageView, explanationImageView, instructionLabel);

            VBox rightButtonArea = new VBox();
            rightButtonArea.setPrefWidth(100);

            mainContentArea.getChildren().addAll(leftButtonArea, whiteBox, rightButtonArea);

            HBox bottomButtonArea = new HBox();
            bottomButtonArea.setAlignment(Pos.CENTER);
            bottomButtonArea.setPrefHeight(45);
            bottomButtonArea.getChildren().add(kembaliButton);

            contentArea.getChildren().addAll(titleImageView, mainContentArea, bottomButtonArea);

            VBox overlayContainer = new VBox();
            overlayContainer.getChildren().addAll(navbar, contentArea);

            view.getChildren().add(overlayContainer);
        }
    }

    public void displayAnimasi(Teknik teknik) {
        // Set title image berdasarkan teknik
        try {
            String titlePath = "/images/" + teknik.getNama() + "_title.png";
            try {
                Image titleImage = new Image(getClass().getResourceAsStream(titlePath));
                titleImageView.setImage(titleImage);
            } catch (Exception titleEx) {
                // Fallback ke teks jika gambar title tidak ada
                titleImageView.setImage(null);
            }
        } catch (Exception e) {
            titleImageView.setImage(null);
        }

        // Set GIF animasi
        try {
            // Coba GIF dulu
            String gifPath = "/images/" + teknik.getNama().toLowerCase() + ".gif";
            try {
                Image gifImage = new Image(getClass().getResourceAsStream(gifPath));
                gifImageView.setImage(gifImage);
            } catch (Exception gifEx) {
                // Fallback ke PNG animasi jika GIF tidak ada
                String pngPath = "/images/animasi_" + teknik.getNama().toLowerCase() + ".png";
                Image staticImage = new Image(getClass().getResourceAsStream(pngPath));
                gifImageView.setImage(staticImage);
            }
        } catch (Exception e) {
            System.err.println("Error loading animation for " + teknik.getNama() + ": " + e.getMessage());
            // Fallback jika gambar tidak ditemukan
            gifImageView.setImage(null);
        }

        // Set gambar animasi teknik
        try {
            String animationPath = "/images/animasi_" + teknik.getNama().toLowerCase() + ".png";
            Image animationImage = new Image(getClass().getResourceAsStream(animationPath));
            explanationImageView.setImage(animationImage);
        } catch (Exception e) {
            System.err.println("Error loading animation image for " + teknik.getNama() + ": " + e.getMessage());
            // Hide animation image if not found
            explanationImageView.setImage(null);
        }

        // Update instruction text
        instructionLabel.setText("Perhatikan gerakan " + teknik.getNama() + " dengan seksama");
    }

    public Parent getView() {
        return view;
    }

    public Button getBackButton() {
        return backButton;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;

/**
 * View untuk menampilkan skor akhir Mencocokkan Gambar sebagai OVERLAY
 * Mirip dengan HasilTebakGambarView - background beige + navbar + overlay tipis + modal kecil
 */
public class HasilMencocokkanGambarView {

    private final BorderPane view;
    private Button mainLagiButton;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    public HasilMencocokkanGambarView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);

        // Tambahkan stylesheet
        view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
        view.getStyleClass().add("root");

        setupOverlayLayout();
    }

    private void setupOverlayLayout() {
        // Set background beige sebagai base
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama dengan background transparan
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas (tetap normal)
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area untuk overlay
            StackPane contentStack = new StackPane();
            contentStack.setPrefSize(1280, 752); // 832 - 80 (navbar height)
            contentStack.setStyle("-fx-background-color: transparent;");

            mainContainer.setCenter(contentStack);

            // Stack background, main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");

            BorderPane mainContainer = new BorderPane();
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            StackPane contentStack = new StackPane();
            contentStack.setPrefSize(1280, 752);
            mainContainer.setCenter(contentStack);

            view.setCenter(mainContainer);
        }
    }

    /**
     * Membuat navbar seperti halaman lain
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    public void displayHasil(int skorBenar, int totalSoal) {
        // Akses content stack
        BorderPane mainContainer = (BorderPane) ((StackPane) view.getCenter()).getChildren().get(1);
        StackPane contentStack = (StackPane) mainContainer.getCenter();

        // Bersihkan content yang ada
        contentStack.getChildren().clear();

        // Overlay gelap tipis (sedikit hitam)
        VBox darkOverlay = new VBox();
        darkOverlay.setPrefSize(1280, 752);
        darkOverlay.setStyle("-fx-background-color: rgba(0, 0, 0, 0.3);");
        darkOverlay.setAlignment(Pos.CENTER);

        // Modal hasil - kotak putih kecil di tengah
        VBox modal = new VBox(25);
        modal.setAlignment(Pos.CENTER);
        modal.setPrefSize(450, 350);
        modal.setMaxSize(450, 350);
        modal.setStyle("-fx-background-color: white; -fx-background-radius: 20; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 15, 0, 0, 5);");
        modal.setPadding(new Insets(40));

        // Header dengan gambar "Skor Akhir"
        try {
            ImageView skorImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Skor Akhir.png")));
            skorImage.setFitHeight(50);
            skorImage.setPreserveRatio(true);
            modal.getChildren().add(skorImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Skor Akhir");
            headerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            modal.getChildren().add(headerLabel);
        }

        // Skor
        int persentase = (int) Math.round((double) skorBenar / totalSoal * 100);

        Label skorLabel = new Label("Skor Anda:");
        skorLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 18px; -fx-font-weight: 600; -fx-text-fill: #1A1E2C;");

        Label nilaiLabel = new Label(skorBenar + " / " + totalSoal + " (" + persentase + "%)");
        nilaiLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 32px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");

        // Pesan berdasarkan skor
        String pesanText;
        String pesanColor;
        if (persentase >= 80) {
            pesanText = "Excellent! Anda menguasai materi dengan baik!";
            pesanColor = "#2ecc71";
        } else if (persentase >= 60) {
            pesanText = "Good job! Terus tingkatkan kemampuan Anda!";
            pesanColor = "#f39c12";
        } else {
            pesanText = "Keep learning! Pelajari kembali materinya ya!";
            pesanColor = "#e74c3c";
        }

        Label pesanLabel = new Label(pesanText);
        pesanLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 500; -fx-text-fill: " + pesanColor + "; -fx-text-alignment: center;");
        pesanLabel.setWrapText(true);
        pesanLabel.setMaxWidth(350);

        modal.getChildren().addAll(skorLabel, nilaiLabel, pesanLabel);

        // Tombol aksi
        HBox buttonContainer = new HBox(15);
        buttonContainer.setAlignment(Pos.CENTER);
        buttonContainer.setPadding(new Insets(20, 0, 0, 0));

        mainLagiButton = new Button("Main Lagi");
        mainLagiButton.setPrefSize(120, 45);
        mainLagiButton.setStyle("-fx-background-color: #516BB0; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-background-radius: 10;");

        kembaliButton = new Button("Kembali");
        kembaliButton.setPrefSize(120, 45);
        kembaliButton.setStyle("-fx-background-color: #F5E6A3; -fx-text-fill: #1A1E2C; -fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-background-radius: 10;");

        buttonContainer.getChildren().addAll(mainLagiButton, kembaliButton);
        modal.getChildren().add(buttonContainer);

        darkOverlay.getChildren().add(modal);
        contentStack.getChildren().add(darkOverlay);
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getMainLagiButton() {
        return mainLagiButton;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }
}

package com.sportedu.view;

import com.sportedu.model.Teknik;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.scene.control.ScrollPane;
import javafx.stage.Stage;

import java.util.List;

/**
 * MainView sekarang multifungsi: bisa menampilkan landing page,
 * halaman pilih materi, dan halaman pilih mode kuis.
 */
public class MainView {

    private final BorderPane root;
    private final Stage stage;

    // Tombol-tombol yang perlu diakses oleh Presenter
    public Button materiButton;
    public Button quizButton;
    public Button kembaliButton;
    public Button sepakBolaButton;
    public Button badmintonButton;
    public Button tebakGambarButton;
    public Button cocokGambarButton;

    // Navbar buttons yang perlu diakses oleh Presenter
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Quiz page buttons yang perlu diakses oleh Presenter
    public Button mulaiButton;
    public Button petunjukButton;

    public MainView(Stage stage) {
        this.stage = stage;
        this.root = new BorderPane();

        // Set ukuran minimum window dan biarkan bisa di-resize
        stage.setMinWidth(1280);
        stage.setMinHeight(832);
        stage.setWidth(1280);
        stage.setHeight(832);
        stage.setResizable(true);

        showLandingPage(); // Tampilan awal
    }

    public Parent getRoot() {
        return root;
    }

    /**
     * Metode untuk mengganti konten utama di tengah BorderPane.
     */
    public void setView(Node view) {
        // Buat ScrollPane untuk mengakomodasi konten yang lebih besar
        ScrollPane scrollPane = new ScrollPane(view);
        scrollPane.setFitToWidth(true); // Konten akan menyesuaikan lebar window
        scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED); // Horizontal scroll jika diperlukan
        scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED); // Vertical scroll jika diperlukan
        scrollPane.setPannable(true); // Bisa di-pan dengan mouse

        // Style ScrollPane agar sesuai dengan desain
        scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");

        root.setCenter(scrollPane);
    }

    /**
     * Membuat navbar transparan dengan logo dan navigasi teks
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        // Change navbar to blue background as per design requirement
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri (hanya logo, tanpa teks)
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);

            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            // Fallback jika logo tidak ditemukan - kosong saja
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer untuk mendorong navigasi ke kanan
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi teks di kanan sesuai desain
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navQuizButton.setOnMouseEntered(e -> navQuizButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navQuizButton.setOnMouseExited(e -> navQuizButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    /**
     * Update navbar untuk menunjukkan tombol mana yang aktif
     */
    private void updateNavbarActiveState(String activePage) {
        // Reset semua tombol ke state normal
        String normalStyle = "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;";
        String activeStyle = "-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;";

        if (navHomeButton != null) {
            navHomeButton.setStyle(normalStyle);
            navHomeButton.setOnMouseEntered(e -> {
                if (!"home".equals(activePage)) {
                    navHomeButton.setStyle(
                            "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
                }
            });
            navHomeButton.setOnMouseExited(e -> {
                if (!"home".equals(activePage)) {
                    navHomeButton.setStyle(normalStyle);
                } else {
                    navHomeButton.setStyle(activeStyle);
                }
            });
        }

        if (navMateriButton != null) {
            navMateriButton.setStyle(normalStyle);
            navMateriButton.setOnMouseEntered(e -> {
                if (!"materi".equals(activePage)) {
                    navMateriButton.setStyle(
                            "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
                }
            });
            navMateriButton.setOnMouseExited(e -> {
                if (!"materi".equals(activePage)) {
                    navMateriButton.setStyle(normalStyle);
                } else {
                    navMateriButton.setStyle(activeStyle);
                }
            });
        }

        if (navQuizButton != null) {
            navQuizButton.setStyle(normalStyle);
            navQuizButton.setOnMouseEntered(e -> {
                if (!"quiz".equals(activePage)) {
                    navQuizButton.setStyle(
                            "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
                }
            });
            navQuizButton.setOnMouseExited(e -> {
                if (!"quiz".equals(activePage)) {
                    navQuizButton.setStyle(normalStyle);
                } else {
                    navQuizButton.setStyle(activeStyle);
                }
            });
        }

        // Set tombol aktif
        switch (activePage) {
            case "home":
                if (navHomeButton != null)
                    navHomeButton.setStyle(activeStyle);
                break;
            case "materi":
                if (navMateriButton != null)
                    navMateriButton.setStyle(activeStyle);
                break;
            case "quiz":
                if (navQuizButton != null)
                    navQuizButton.setStyle(activeStyle);
                break;
        }
    }

    /**
     * Membuat dan menampilkan Landing Page sesuai desain "1. Landing Page.png"
     */
    public void showLandingPage() {
        // Container utama dengan background dot pattern
        VBox mainContainer = new VBox();
        mainContainer.setPrefSize(1280, 832);

        // Background dengan dot pattern dari vektor
        try {
            ImageView dotBackground = new ImageView(
                    new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Overlay container untuk konten
            VBox overlayContainer = new VBox();
            overlayContainer.setPrefSize(1280, 832);
            overlayContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();

            // Content area utama dengan background box
            VBox contentArea = new VBox(40);
            contentArea.setAlignment(Pos.CENTER);
