            fallbackContainer.getChildren().addAll(navbar, contentArea);
            setView(fallbackContainer);
        }
        updateNavbarActiveState("quiz");
    }

    /**
     * Membuat dan mengatur footer di bagian bawah layar
     */
    private void createAndSetFooter() {
        try {
            // Load footer image
            ImageView footerImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Footer.png")));
            
            // Set footer to fit the full width of the screen but maintain aspect ratio
            footerImage.setFitWidth(1280);
            footerImage.setPreserveRatio(true);
            footerImage.setSmooth(true);
            
            // Create container for footer
            HBox footerContainer = new HBox();
            footerContainer.setAlignment(Pos.CENTER);
            footerContainer.setStyle("-fx-background-color: transparent;");
            footerContainer.getChildren().add(footerImage);
            
            // Set footer to bottom of BorderPane
            root.setBottom(footerContainer);
            
        } catch (Exception e) {
            System.err.println("Footer image not found: " + e.getMessage());
            // Create a simple text footer as fallback
            Label footerLabel = new Label("SportEdu - Platform Pembelajaran Olahraga Interaktif");
            footerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 12px; -fx-text-fill: #666; -fx-padding: 10;");
            
            HBox footerContainer = new HBox();
            footerContainer.setAlignment(Pos.CENTER);
            footerContainer.setStyle("-fx-background-color: #f0f0f0; -fx-border-color: #ccc; -fx-border-width: 1 0 0 0;");
            footerContainer.getChildren().add(footerLabel);
            
            root.setBottom(footerContainer);
        }
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * View untuk kuis mencocokkan gambar dengan navbar, scrolling, dan connection
 * dots
 * Fix size 1280x832 dengan scroll jika konten lebih panjang
 */
public class MatchingQuizFXView {

    // Interface untuk callback ketika game selesai
    public interface OnGameCompleteListener {
        void onGameComplete(int correctAnswers, int totalQuestions);
    }

    // Interface untuk callback ketika match attempt
    public interface OnMatchAttemptListener {
        void onMatchAttempt(boolean isCorrect);
    }

    // Interface untuk callback ketika next round
    public interface OnNextRoundListener {
        void onNextRound();
    }

    // Interface untuk callback navigasi
    public interface OnNavigationListener {
        void onNavigateToHome();

        void onNavigateToMateri();

        void onNavigateToQuiz();

        void onNavigateBack();
    }

    private final BorderPane view;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Container untuk lines
    private Pane lineContainer;

    // Data untuk matching
    private List<String> imagePaths;
    private List<String> answerTexts;
    private List<String> imageIds;
    private List<String> correctAnswerIds;

    // Tracking connections
    private final Map<String, String> connections = new HashMap<>();
    private final Map<String, Button> imageButtons = new HashMap<>();
    private final Map<String, Button> answerButtons = new HashMap<>();
    private final Map<String, Line> connectionLines = new HashMap<>();

    // Line drawing
    private String selectedImageId = null;

    // Game completion callbacks
    private OnGameCompleteListener onGameComplete;
    private OnMatchAttemptListener onMatchAttempt;
    private OnNextRoundListener onNextRound;
    private OnNavigationListener onNavigation;

    // Round data
    private int currentRound;
    private int totalRounds;

    public MatchingQuizFXView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);
        view.setMaxSize(1280, 832);

        // Initialize kembali button even though it won't be displayed
        kembaliButton = new Button("Kembali");
        kembaliButton.setVisible(false); // Hide it but keep it initialized

        // Tambahkan stylesheet
        try {
            view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
            view.getStyleClass().add("root");
        } catch (Exception e) {
            System.err.println("Could not load stylesheet: " + e.getMessage());
        }

        setupLayout();
    }

    private void setupLayout() {
        // Set background beige
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(
                    new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area dengan scroll
            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752); // 832 - 80 (navbar)
            scrollPane.setMaxSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            // Content container
            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);

            mainContainer.setCenter(scrollPane);

            // Stack background dan main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");
            System.err.println("Gagal memuat dot background: " + e.getMessage());

            // Simple layout without background image
            BorderPane mainContainer = new BorderPane();
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);
            mainContainer.setCenter(scrollPane);

            view.setCenter(mainContainer);
        }
    }

    private VBox createContentContainer() {
        VBox container = new VBox(40);
        container.setAlignment(Pos.TOP_CENTER);
        container.setPadding(new Insets(40, 50, 40, 50));
        container.setStyle("-fx-background-color: transparent;");
        container.setMinHeight(800); // Minimum height untuk memastikan scroll berfungsi

        // Header dengan gambar "Cocokkan Gambar"
        VBox headerSection = new VBox(30);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView headerImage = new ImageView(
                    new Image(getClass().getResourceAsStream("/images/Cocokkan Gambar.png")));
            headerImage.setFitHeight(60);
            headerImage.setPreserveRatio(true);
            headerSection.getChildren().add(headerImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Mencocokkan Gambar");
            headerLabel.setStyle(
                    "-fx-font-family: 'Poppins', Arial; -fx-font-size: 28px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            headerSection.getChildren().add(headerLabel);
        }

        // Instruksi dengan warna biru dan tebal
        Label instruksiLabel = new Label(
                "Hubungkan gambar dengan jawaban yang tepat dengan menarik garis dari titik ke titik");
        instruksiLabel.setStyle(
                "-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        instruksiLabel.setWrapText(true);
        instruksiLabel.setMaxWidth(600);
        headerSection.getChildren().add(instruksiLabel);

        container.getChildren().add(headerSection);
        return container;
    }

    /**
     * Setup matching game dengan data gambar dan jawaban
     */
    public void setupMatchingGame(List<String> imagePaths, List<String> answerTexts, List<String> imageIds,
            List<String> correctAnswerIds) {
        this.imagePaths = imagePaths;
        this.answerTexts = answerTexts;
        this.imageIds = imageIds;
        this.correctAnswerIds = correctAnswerIds;

        // Clear previous connections
        connections.clear();
        imageButtons.clear();
        answerButtons.clear();
        connectionLines.clear();

        // Get content container
        VBox contentContainer = (VBox) ((ScrollPane) ((BorderPane) ((StackPane) view.getCenter()).getChildren().get(1))
                .getCenter()).getContent();

        // Clear previous game content (keep header)
        if (contentContainer.getChildren().size() > 1) {
            contentContainer.getChildren().subList(1, contentContainer.getChildren().size()).clear();
        }

        // Game area dengan line container
        StackPane gameArea = new StackPane();
        gameArea.setPrefHeight(600);
        gameArea.setMaxHeight(600);

        // Line container untuk menggambar garis (di layer paling atas)
        lineContainer = new Pane();
        lineContainer.setPrefSize(1180, 600);
        lineContainer.setStyle("-fx-background-color: transparent;");
        lineContainer.setMouseTransparent(true); // Allow clicks to pass through

        // Main game layout
        HBox gameLayout = new HBox(150); // Space between columns
        gameLayout.setAlignment(Pos.CENTER);
        gameLayout.setPadding(new Insets(50));

        // Left side - Images
        VBox imageColumn = createImageColumn();

        // Right side - Answers
        VBox answerColumn = createAnswerColumn();

        gameLayout.getChildren().addAll(imageColumn, answerColumn);

        // Add game layout first, then line container on top
        gameArea.getChildren().addAll(gameLayout, lineContainer);

        contentContainer.getChildren().add(gameArea);

        // Add Kembali button at the bottom
        HBox buttonSection = new HBox();
        buttonSection.setAlignment(Pos.CENTER);
        buttonSection.setPadding(new Insets(30, 0, 20, 0));

        // Create visible and functional Kembali button
        kembaliButton = new Button("Kembali");
        kembaliButton.setVisible(true);
        kembaliButton.setPrefSize(120, 40);
        kembaliButton.setStyle(
                "-fx-background-color: #e74c3c; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 5, 0, 0, 2);");

        // Add hover effects
        kembaliButton.setOnMouseEntered(e -> kembaliButton.setStyle(
                "-fx-background-color: #c0392b; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.4), 8, 0, 0, 3);"));

        kembaliButton.setOnMouseExited(e -> kembaliButton.setStyle(
                "-fx-background-color: #e74c3c; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 5, 0, 0, 2);"));

        // Set navigation action
        kembaliButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateBack();
            }
        });

        buttonSection.getChildren().add(kembaliButton);
        contentContainer.getChildren().add(buttonSection);
    }

    private VBox createImageColumn() {
        VBox imageColumn = new VBox(40);
        imageColumn.setAlignment(Pos.CENTER_LEFT);
        imageColumn.setPrefWidth(450);

        // Remove subtitle - no "Gambar" label

        for (int i = 0; i < imagePaths.size(); i++) {
            HBox imageRow = createImageRow(imagePaths.get(i), imageIds.get(i), i);
            imageColumn.getChildren().add(imageRow);
        }

        return imageColumn;
    }

    private HBox createImageRow(String imagePath, String imageId, int index) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_LEFT);

        // Image container with white background that adapts to image size with padding
        VBox imageContainer = new VBox();
        imageContainer.setAlignment(Pos.CENTER);
        imageContainer.setStyle(
                "-fx-background-color: white; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4); -fx-padding: 15;");

        try {
            ImageView imageView = new ImageView(new Image(getClass().getResourceAsStream(imagePath)));
            // Let image maintain its natural proportions but with max constraints
            imageView.setFitWidth(180);
            imageView.setFitHeight(110);
            imageView.setPreserveRatio(true);

            // Container adapts to image size plus padding (stroke effect)
            imageContainer.getChildren().add(imageView);

            // Set container size based on image bounds plus padding
            imageContainer.setPrefSize(210, 140); // Added extra space for stroke effect
        } catch (Exception e) {
            Label placeholder = new Label("Gambar " + (index + 1));
            placeholder.setStyle("-fx-font-size: 16px; -fx-text-fill: #666;");
            imageContainer.getChildren().add(placeholder);
            imageContainer.setPrefSize(210, 140);
        }

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle(
                "-fx-background-color: white; -fx-border-width: 2; -fx-border-color: #ccc; -fx-background-radius: 17; -fx-padding: 0;");

        // Force white circles instead of using image
        // try {
        // ImageView dotIcon = new ImageView(
        // new Image(getClass().getResourceAsStream("/images/Cocokkan gambar
        // titik.png")));
        // dotIcon.setFitWidth(30);
        // dotIcon.setFitHeight(30);
        // dotIcon.setPreserveRatio(true);
        // connectPoint.setGraphic(dotIcon);
        // } catch (Exception e) {
        // // Fallback: larger white circle
        // connectPoint.setStyle("-fx-background-color: white; -fx-background-radius:
        // 17; -fx-border-width: 0;");
        // }

        connectPoint.setOnAction(e -> startConnection(imageId, connectPoint));

        imageButtons.put(imageId, connectPoint);
        row.getChildren().addAll(imageContainer, connectPoint);
        return row;
    }

    private VBox createAnswerColumn() {
        VBox answerColumn = new VBox(40);
        answerColumn.setAlignment(Pos.CENTER_RIGHT);
        answerColumn.setPrefWidth(450);

        // Remove subtitle - no "Jawaban" label

        for (int i = 0; i < answerTexts.size(); i++) {
            HBox answerRow = createAnswerRow(answerTexts.get(i), imageIds.get(i));
            answerColumn.getChildren().add(answerRow);
        }

        return answerColumn;
    }

    private HBox createAnswerRow(String answerText, String answerId) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_RIGHT);

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle(
                "-fx-background-color: white; -fx-border-width: 2; -fx-border-color: #ccc; -fx-background-radius: 17; -fx-padding: 0;");

        // Force white circles instead of using image
        // try {
        // ImageView dotIcon = new ImageView(
        // new Image(getClass().getResourceAsStream("/images/Cocokkan gambar
        // titik.png")));
        // dotIcon.setFitWidth(30);
        // dotIcon.setFitHeight(30);
        // dotIcon.setPreserveRatio(true);
        // connectPoint.setGraphic(dotIcon);
        // } catch (Exception e) {
        // // Fallback: larger white circle
        // connectPoint.setStyle("-fx-background-color: white; -fx-background-radius:
        // 17; -fx-border-width: 0;");
        // }

        connectPoint.setOnAction(e -> completeConnection(answerId, connectPoint));

        // Answer container with white background
        VBox answerContainer = new VBox();
        answerContainer.setAlignment(Pos.CENTER);
        answerContainer.setPrefSize(200, 130);
        answerContainer.setStyle(
                "-fx-background-color: white; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4);");

        // Answer label with blue text, bolder and centered
        Label answerLabel = new Label(answerText);
        answerLabel.setStyle(
                "-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        answerLabel.setWrapText(true);
        answerLabel.setMaxWidth(180);
        answerLabel.setAlignment(Pos.CENTER); // Ensure text is centered
        answerContainer.getChildren().add(answerLabel);

        answerButtons.put(answerId, connectPoint);
        row.getChildren().addAll(connectPoint, answerContainer);
        return row;
    }

    private void startConnection(String imageId, Button imageButton) {
        // Clear previous selection
        resetAllButtonStyles();

        selectedImageId = imageId;

        // Visual feedback - highlight selected image point with white circle and green
        // effect
        // effect
        imageButton.setGraphic(null); // Remove any image
                "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #2ecc71; -fx-effect: dropshadow(gaussian, #2ecc71, 10, 0, 0, 0);");
                "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #2ecc71; -fx-effect: dropshadow(gaussian, #2ecc71, 10, 0, 0, 0);");
        // If there was a previous connection from this image, highlight the connected
        // answer
        // If there was a previous connection from this image, highlight the connected
        // answer
        String connectedAnswerId = connections.get(imageId);
        if (connectedAnswerId != null) {
            Button answerButton = answerButtons.get(connectedAnswerId);
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #e74c3c; -fx-effect: dropshadow(gaussian, #e74c3c, 10, 0, 0, 0);");
        if (selectedImageId != null) {
            // Remove old connection if exists
            String oldAnswer = connections.get(selectedImageId);
            if (oldAnswer != null) {
                Line oldLine = connectionLines.get(selectedImageId);
                if (oldLine != null) {
                    lineContainer.getChildren().remove(oldLine);
                }
            }

            // Create new connection
            Button imageButton = imageButtons.get(selectedImageId);
            Line line = createConnectionLine(imageButton, answerButton);

            // All lines are blue regardless of correctness
            line.setStroke(Color.web("#516BB0")); // Blue for all connections

            lineContainer.getChildren().add(line);
            // All lines are blue regardless of correctness
            line.setStroke(Color.web("#516BB0")); // Blue for all connections

            lineContainer.getChildren().add(line);
            connections.put(selectedImageId, answerId);
            connectionLines.put(selectedImageId, line);

            // Check if answer is correct for scoring
            connectionLines.put(selectedImageId, line);

            // Check if answer is correct for scoring
            boolean isCorrect = false;
            for (int i = 0; i < imageIds.size(); i++) {
                if (imageIds.get(i).equals(selectedImageId) && correctAnswerIds.get(i).equals(answerId)) {
                    isCorrect = true;
                    break;

            // Check if all connections are made
            checkAllConnectionsComplete();
        }
    }

    private Line createConnectionLine(Button startButton, Button endButton) {
        Line line = new Line();

        // Use layout bounds in scene for more accurate positioning
        javafx.geometry.Bounds startBounds = startButton.localToScene(startButton.getBoundsInLocal());
        javafx.geometry.Bounds endBounds = endButton.localToScene(endButton.getBoundsInLocal());
        javafx.geometry.Bounds containerBounds = lineContainer.localToScene(lineContainer.getBoundsInLocal());

        // Calculate center points relative to line container
        double startX = startBounds.getCenterX() - containerBounds.getMinX();
        double startY = startBounds.getCenterY() - containerBounds.getMinY();
        double endX = endBounds.getCenterX() - containerBounds.getMinX();
        double endY = endBounds.getCenterY() - containerBounds.getMinY();

        line.setStartX(startX);
        line.setStartY(startY);
        line.setEndX(endX);
        line.setEndY(endY);

        line.setStrokeWidth(4);
        line.setOpacity(0.9);

        return line;
    }

    private void checkAllConnectionsComplete() {
        // Check if all images have connections
        if (connections.size() == imageIds.size()) {
            // All connections made - automatically proceed to next round or show results
            javafx.application.Platform.runLater(() -> {
                try {
                    Thread.sleep(1000); // Brief pause to show all lines
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                if (onNextRound != null) {
                    onNextRound.onNextRound();
                } else {
                    checkAnswers();
                }
            });
        }
    }

    private void resetAllButtonStyles() {
        // Reset image buttons to white circles
        for (Button button : imageButtons.values()) {
            button.setGraphic(null); // Remove any image
            button.setStyle(
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #ccc;");
        }

        // Reset answer buttons to white circles
        for (Button button : answerButtons.values()) {
            button.setGraphic(null); // Remove any image
            button.setStyle(
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #ccc;");
        }
    }

    private void checkAnswers() {
        int correctAnswers = 0;

        // Count correct answers
        for (int i = 0; i < imageIds.size(); i++) {
            String imageId = imageIds.get(i);
            String userAnswer = connections.get(imageId);
            String correctAnswer = correctAnswerIds.get(i);

            if (userAnswer != null && userAnswer.equals(correctAnswer)) {
                correctAnswers++;
            }
        }

        // Trigger callback with results
        if (onGameComplete != null) {
            onGameComplete.onGameComplete(correctAnswers, imageIds.size());
        }
    }

    /**
     * Membuat navbar dengan logo dan tombol navigasi
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            Label logoText = new Label("SportEdu");
            logoText.setStyle(
                    "-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: white;");
            logoContainer.getChildren().add(logoText);
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToHome();
            }
        });

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToMateri();
            }
        });

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle(
                "-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");
        navQuizButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToQuiz();
            }
        });

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }

    public void setOnGameComplete(OnGameCompleteListener listener) {
        this.onGameComplete = listener;
    }

    // Methods expected by MainPresenter
    public void setRound(int round, int totalRounds, List<String> imagePaths, List<String> answerTexts,
            List<String> imageIds) {
        this.currentRound = round;
        this.totalRounds = totalRounds;

        // Use the first 4 images as correct answers (same order)
        List<String> correctIds = new ArrayList<>(imageIds);

        setupMatchingGame(imagePaths, answerTexts, imageIds, correctIds);
    }

    public void setOnMatchAttempt(OnMatchAttemptListener listener) {
        this.onMatchAttempt = listener;
    }

    public void setOnNextRound(OnNextRoundListener listener) {
        this.onNextRound = listener;
    }

    public void setOnNavigation(OnNavigationListener listener) {
        this.onNavigation = listener;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * View untuk kuis mencocokkan gambar dengan navbar, scrolling, dan connection
 * dots
 * Fix size 1280x832 dengan scroll jika konten lebih panjang
 */
public class MatchingQuizFXView {

    // Interface untuk callback ketika game selesai
    public interface OnGameCompleteListener {
        void onGameComplete(int correctAnswers, int totalQuestions);
    }

    // Interface untuk callback ketika match attempt
    public interface OnMatchAttemptListener {
        void onMatchAttempt(boolean isCorrect);
    }

    // Interface untuk callback ketika next round
    public interface OnNextRoundListener {
        void onNextRound();
    }

    // Interface untuk callback navigasi
    public interface OnNavigationListener {
        void onNavigateToHome();

        void onNavigateToMateri();

        void onNavigateToQuiz();

        void onNavigateBack();
    }

    private final BorderPane view;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Container untuk lines
    private Pane lineContainer;

    // Data untuk matching
    private List<String> imagePaths;
    private List<String> answerTexts;
    private List<String> imageIds;
    private List<String> correctAnswerIds;

    // Tracking connections
    private final Map<String, String> connections = new HashMap<>();
    private final Map<String, Button> imageButtons = new HashMap<>();
    private final Map<String, Button> answerButtons = new HashMap<>();
    private final Map<String, Line> connectionLines = new HashMap<>();

    // Line drawing
    private String selectedImageId = null;

    // Game completion callbacks
    private OnGameCompleteListener onGameComplete;
    private OnMatchAttemptListener onMatchAttempt;
    private OnNextRoundListener onNextRound;
    private OnNavigationListener onNavigation;

    // Round data
    private int currentRound;
    private int totalRounds;

    public MatchingQuizFXView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);
        view.setMaxSize(1280, 832);

        // Initialize kembali button even though it won't be displayed
        kembaliButton = new Button("Kembali");
        kembaliButton.setVisible(false); // Hide it but keep it initialized

        // Tambahkan stylesheet
        try {
            view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
            view.getStyleClass().add("root");
        } catch (Exception e) {
            System.err.println("Could not load stylesheet: " + e.getMessage());
        }

        setupLayout();
    }

    private void setupLayout() {
        // Set background beige
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(
                    new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area dengan scroll
            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752); // 832 - 80 (navbar)
            scrollPane.setMaxSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            // Content container
            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);

            mainContainer.setCenter(scrollPane);

            // Stack background dan main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");
            System.err.println("Gagal memuat dot background: " + e.getMessage());

            // Simple layout without background image
            BorderPane mainContainer = new BorderPane();
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);
            mainContainer.setCenter(scrollPane);

            view.setCenter(mainContainer);
        }
    }

    private VBox createContentContainer() {
        VBox container = new VBox(40);
        container.setAlignment(Pos.TOP_CENTER);
        container.setPadding(new Insets(40, 50, 40, 50));
        container.setStyle("-fx-background-color: transparent;");
        container.setMinHeight(800); // Minimum height untuk memastikan scroll berfungsi

        // Header dengan gambar "Cocokkan Gambar"
        VBox headerSection = new VBox(30);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView headerImage = new ImageView(
                    new Image(getClass().getResourceAsStream("/images/Cocokkan Gambar.png")));
            headerImage.setFitHeight(60);
            headerImage.setPreserveRatio(true);
            headerSection.getChildren().add(headerImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Mencocokkan Gambar");
            headerLabel.setStyle(
                    "-fx-font-family: 'Poppins', Arial; -fx-font-size: 28px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            headerSection.getChildren().add(headerLabel);
        }

        // Instruksi dengan warna biru dan tebal
        Label instruksiLabel = new Label(
                "Hubungkan gambar dengan jawaban yang tepat dengan menarik garis dari titik ke titik");
        instruksiLabel.setStyle(
                "-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        instruksiLabel.setWrapText(true);
        instruksiLabel.setMaxWidth(600);
        headerSection.getChildren().add(instruksiLabel);

        container.getChildren().add(headerSection);
        return container;
    }

    /**
     * Setup matching game dengan data gambar dan jawaban
     */
    public void setupMatchingGame(List<String> imagePaths, List<String> answerTexts, List<String> imageIds,
            List<String> correctAnswerIds) {
        this.imagePaths = imagePaths;
        this.answerTexts = answerTexts;
        this.imageIds = imageIds;
        this.correctAnswerIds = correctAnswerIds;

        // Clear previous connections
        connections.clear();
        imageButtons.clear();
        answerButtons.clear();
        connectionLines.clear();

        // Get content container
        VBox contentContainer = (VBox) ((ScrollPane) ((BorderPane) ((StackPane) view.getCenter()).getChildren().get(1))
                .getCenter()).getContent();

        // Clear previous game content (keep header)
        if (contentContainer.getChildren().size() > 1) {
            contentContainer.getChildren().subList(1, contentContainer.getChildren().size()).clear();
        }

        // Game area dengan line container
        StackPane gameArea = new StackPane();
        gameArea.setPrefHeight(600);
        gameArea.setMaxHeight(600);

        // Line container untuk menggambar garis (di layer paling atas)
        lineContainer = new Pane();
        lineContainer.setPrefSize(1180, 600);
        lineContainer.setStyle("-fx-background-color: transparent;");
        lineContainer.setMouseTransparent(true); // Allow clicks to pass through

        // Main game layout
        HBox gameLayout = new HBox(150); // Space between columns
        gameLayout.setAlignment(Pos.CENTER);
        gameLayout.setPadding(new Insets(50));

        // Left side - Images
        VBox imageColumn = createImageColumn();

        // Right side - Answers
        VBox answerColumn = createAnswerColumn();

        gameLayout.getChildren().addAll(imageColumn, answerColumn);

        // Add game layout first, then line container on top
        gameArea.getChildren().addAll(gameLayout, lineContainer);

        contentContainer.getChildren().add(gameArea);

        // Add Kembali button at the bottom
        HBox buttonSection = new HBox();
        buttonSection.setAlignment(Pos.CENTER);
        buttonSection.setPadding(new Insets(30, 0, 20, 0));

        // Create visible and functional Kembali button
        kembaliButton = new Button("Kembali");
        kembaliButton.setVisible(true);
        kembaliButton.setPrefSize(120, 40);
        kembaliButton.setStyle(
                "-fx-background-color: #e74c3c; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 5, 0, 0, 2);");

        // Add hover effects
        kembaliButton.setOnMouseEntered(e -> kembaliButton.setStyle(
                "-fx-background-color: #c0392b; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.4), 8, 0, 0, 3);"));

        kembaliButton.setOnMouseExited(e -> kembaliButton.setStyle(
                "-fx-background-color: #e74c3c; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; " +
                        "-fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 20; -fx-border-width: 0; " +
                        "-fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 5, 0, 0, 2);"));

        // Set navigation action
        kembaliButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateBack();
            }
        });

        buttonSection.getChildren().add(kembaliButton);
        contentContainer.getChildren().add(buttonSection);
    }

    private VBox createImageColumn() {
        VBox imageColumn = new VBox(40);
        imageColumn.setAlignment(Pos.CENTER_LEFT);
        imageColumn.setPrefWidth(450);

        // Remove subtitle - no "Gambar" label

        for (int i = 0; i < imagePaths.size(); i++) {
            HBox imageRow = createImageRow(imagePaths.get(i), imageIds.get(i), i);
            imageColumn.getChildren().add(imageRow);
        }

        return imageColumn;
    }

    private HBox createImageRow(String imagePath, String imageId, int index) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_LEFT);

        // Image container with white background that adapts to image size with padding
        VBox imageContainer = new VBox();
        imageContainer.setAlignment(Pos.CENTER);
        imageContainer.setStyle(
                "-fx-background-color: white; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4); -fx-padding: 15;");

        try {
            ImageView imageView = new ImageView(new Image(getClass().getResourceAsStream(imagePath)));
            // Let image maintain its natural proportions but with max constraints
            imageView.setFitWidth(180);
            imageView.setFitHeight(110);
            imageView.setPreserveRatio(true);

            // Container adapts to image size plus padding (stroke effect)
            imageContainer.getChildren().add(imageView);

            // Set container size based on image bounds plus padding
            imageContainer.setPrefSize(210, 140); // Added extra space for stroke effect
        } catch (Exception e) {
            Label placeholder = new Label("Gambar " + (index + 1));
            placeholder.setStyle("-fx-font-size: 16px; -fx-text-fill: #666;");
            imageContainer.getChildren().add(placeholder);
            imageContainer.setPrefSize(210, 140);
        }

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle(
                "-fx-background-color: white; -fx-border-width: 2; -fx-border-color: #ccc; -fx-background-radius: 17; -fx-padding: 0;");

        // Force white circles instead of using image
        // try {
        // ImageView dotIcon = new ImageView(
        // new Image(getClass().getResourceAsStream("/images/Cocokkan gambar
        // titik.png")));
        // dotIcon.setFitWidth(30);
        // dotIcon.setFitHeight(30);
        // dotIcon.setPreserveRatio(true);
        // connectPoint.setGraphic(dotIcon);
        // } catch (Exception e) {
        // // Fallback: larger white circle
        // connectPoint.setStyle("-fx-background-color: white; -fx-background-radius:
        // 17; -fx-border-width: 0;");
        // }

        connectPoint.setOnAction(e -> startConnection(imageId, connectPoint));

        imageButtons.put(imageId, connectPoint);
        row.getChildren().addAll(imageContainer, connectPoint);
        return row;
    }

    private VBox createAnswerColumn() {
        VBox answerColumn = new VBox(40);
        answerColumn.setAlignment(Pos.CENTER_RIGHT);
        answerColumn.setPrefWidth(450);

        // Remove subtitle - no "Jawaban" label

        for (int i = 0; i < answerTexts.size(); i++) {
            HBox answerRow = createAnswerRow(answerTexts.get(i), imageIds.get(i));
            answerColumn.getChildren().add(answerRow);
        }

        return answerColumn;
    }

    private HBox createAnswerRow(String answerText, String answerId) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_RIGHT);

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle(
                "-fx-background-color: white; -fx-border-width: 2; -fx-border-color: #ccc; -fx-background-radius: 17; -fx-padding: 0;");

        // Force white circles instead of using image
        // try {
        // ImageView dotIcon = new ImageView(
        // new Image(getClass().getResourceAsStream("/images/Cocokkan gambar
        // titik.png")));
        // dotIcon.setFitWidth(30);
        // dotIcon.setFitHeight(30);
        // dotIcon.setPreserveRatio(true);
        // connectPoint.setGraphic(dotIcon);
        // } catch (Exception e) {
        // // Fallback: larger white circle
        // connectPoint.setStyle("-fx-background-color: white; -fx-background-radius:
        // 17; -fx-border-width: 0;");
        // }

        connectPoint.setOnAction(e -> completeConnection(answerId, connectPoint));

        // Answer container with white background
        VBox answerContainer = new VBox();
        answerContainer.setAlignment(Pos.CENTER);
        answerContainer.setPrefSize(200, 130);
        answerContainer.setStyle(
                "-fx-background-color: white; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4);");

        // Answer label with blue text, bolder and centered
        Label answerLabel = new Label(answerText);
        answerLabel.setStyle(
                "-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        answerLabel.setWrapText(true);
        answerLabel.setMaxWidth(180);
        answerLabel.setAlignment(Pos.CENTER); // Ensure text is centered
        answerContainer.getChildren().add(answerLabel);

        answerButtons.put(answerId, connectPoint);
        row.getChildren().addAll(connectPoint, answerContainer);
        return row;
    }

    private void startConnection(String imageId, Button imageButton) {
        // Clear previous selection
        resetAllButtonStyles();

        selectedImageId = imageId;

        // Visual feedback - highlight selected image point with white circle and blue effect
        imageButton.setGraphic(null); // Remove any image
        imageButton.setStyle(
                "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #516BB0; -fx-effect: dropshadow(gaussian, #516BB0, 10, 0, 0, 0);");

        // If there was a previous connection from this image, show the line as blue (being drawn)
        String connectedAnswerId = connections.get(imageId);
        if (connectedAnswerId != null) {
            Button answerButton = answerButtons.get(connectedAnswerId);
            answerButton.setGraphic(null); // Remove any image
            answerButton.setStyle(
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #516BB0; -fx-effect: dropshadow(gaussian, #516BB0, 10, 0, 0, 0);");

            // Change existing line to blue (being dragged)
            Line existingLine = connectionLines.get(imageId);
            if (existingLine != null) {
                existingLine.setStroke(Color.web("#516BB0")); // Blue when being dragged
            }
        }
    }

    private void completeConnection(String answerId, Button answerButton) {
        if (selectedImageId != null) {
            // Remove old connection if exists
            String oldAnswer = connections.get(selectedImageId);
            if (oldAnswer != null) {
                Line oldLine = connectionLines.get(selectedImageId);
                if (oldLine != null) {
                    lineContainer.getChildren().remove(oldLine);
                }
            }

            // Create new connection
            Button imageButton = imageButtons.get(selectedImageId);
            Line line = createConnectionLine(imageButton, answerButton);

            // Check if answer is correct for line color
            boolean isCorrect = false;
            for (int i = 0; i < imageIds.size(); i++) {
                if (imageIds.get(i).equals(selectedImageId) && correctAnswerIds.get(i).equals(answerId)) {
                    isCorrect = true;
                    break;
                }
            }

            // Set line color based on correctness
            if (isCorrect) {
                line.setStroke(Color.GREEN); // Hijau jika benar
            } else {
                line.setStroke(Color.RED);   // Merah jika salah
            }

            lineContainer.getChildren().add(line);
            connections.put(selectedImageId, answerId);
            connectionLines.put(selectedImageId, line);

            // Notify match attempt
            if (onMatchAttempt != null) {
                onMatchAttempt.onMatchAttempt(isCorrect);
            }

            // Reset visual feedback
            resetAllButtonStyles();
            selectedImageId = null;

            // Check if all connections are made
            checkAllConnectionsComplete();
        }
    }

    private Line createConnectionLine(Button startButton, Button endButton) {
        Line line = new Line();

        // Use layout bounds in scene for more accurate positioning
        javafx.geometry.Bounds startBounds = startButton.localToScene(startButton.getBoundsInLocal());
        javafx.geometry.Bounds endBounds = endButton.localToScene(endButton.getBoundsInLocal());
        javafx.geometry.Bounds containerBounds = lineContainer.localToScene(lineContainer.getBoundsInLocal());

        // Calculate center points relative to line container
        double startX = startBounds.getCenterX() - containerBounds.getMinX();
        double startY = startBounds.getCenterY() - containerBounds.getMinY();
        double endX = endBounds.getCenterX() - containerBounds.getMinX();
        double endY = endBounds.getCenterY() - containerBounds.getMinY();

        line.setStartX(startX);
        line.setStartY(startY);
        line.setEndX(endX);
        line.setEndY(endY);

        line.setStrokeWidth(4);
        line.setOpacity(0.9);

        return line;
    }

    private void checkAllConnectionsComplete() {
        // Check if all images have connections
        if (connections.size() == imageIds.size()) {
            // All connections made - automatically proceed to next round or show results
            javafx.application.Platform.runLater(() -> {
                try {
                    Thread.sleep(1000); // Brief pause to show all lines
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                if (onNextRound != null) {
                    onNextRound.onNextRound();
                } else {
                    checkAnswers();
                }
            });
        }
    }

    private void resetAllButtonStyles() {
        // Reset image buttons to white circles
        for (Button button : imageButtons.values()) {
            button.setGraphic(null); // Remove any image
            button.setStyle(
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #ccc;");
        }

        // Reset answer buttons to white circles
        for (Button button : answerButtons.values()) {
            button.setGraphic(null); // Remove any image
            button.setStyle(
                    "-fx-background-color: white; -fx-background-radius: 17; -fx-border-width: 2; -fx-border-color: #ccc;");
        }
    }

    private void checkAnswers() {
        int correctAnswers = 0;

        // Count correct answers
        for (int i = 0; i < imageIds.size(); i++) {
            String imageId = imageIds.get(i);
            String userAnswer = connections.get(imageId);
            String correctAnswer = correctAnswerIds.get(i);

            if (userAnswer != null && userAnswer.equals(correctAnswer)) {
                correctAnswers++;
            }
        }

        // Trigger callback with results
        if (onGameComplete != null) {
            onGameComplete.onGameComplete(correctAnswers, imageIds.size());
        }
    }

    /**
     * Membuat navbar dengan logo dan tombol navigasi
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            Label logoText = new Label("SportEdu");
            logoText.setStyle(
                    "-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: white;");
            logoContainer.getChildren().add(logoText);
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToHome();
            }
        });

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle(
                "-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToMateri();
            }
        });

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle(
                "-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");
        navQuizButton.setOnAction(e -> {
            if (onNavigation != null) {
                onNavigation.onNavigateToQuiz();
            }
        });

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }

    public void setOnGameComplete(OnGameCompleteListener listener) {
        this.onGameComplete = listener;
    }

    // Methods expected by MainPresenter
    public void setRound(int round, int totalRounds, List<String> imagePaths, List<String> answerTexts,
            List<String> imageIds) {
        this.currentRound = round;
        this.totalRounds = totalRounds;

        // Use the first 4 images as correct answers (same order)
        List<String> correctIds = new ArrayList<>(imageIds);

        setupMatchingGame(imagePaths, answerTexts, imageIds, correctIds);
    }

    public void setOnMatchAttempt(OnMatchAttemptListener listener) {
        this.onMatchAttempt = listener;
    }

    public void setOnNextRound(OnNextRoundListener listener) {
        this.onNextRound = listener;
    }

    public void setOnNavigation(OnNavigationListener listener) {
        this.onNavigation = listener;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;
import javafx.scene.Node;
import java.util.List;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;

/**
 * View untuk halaman mencocokkan gambar dengan fitur drag-and-drop
 * Fix size 1280x832 dengan scroll jika konten lebih panjang
 */
public class MencocokkanGambarView {

    // Interface untuk callback ketika game selesai
    public interface OnGameCompleteListener {
        void onGameComplete(int correctAnswers, int totalQuestions);
    }

    private final BorderPane view;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Container untuk lines
    private Pane lineContainer;

    // Data untuk matching
    private List<String> imagePaths;
    private List<String> answerTexts;
    private List<String> imageIds;
    private List<String> correctAnswerIds; // ID jawaban yang benar untuk setiap gambar

    // Tracking connections
    private Map<String, String> connections = new HashMap<>();
    private Map<String, Button> imageButtons = new HashMap<>();
    private Map<String, Button> answerButtons = new HashMap<>();
    private Map<String, Line> connectionLines = new HashMap<>();

    // Line drawing
    private Line currentLine = null;
    private String selectedImageId = null;

    // Game completion callback
    private OnGameCompleteListener onGameComplete;

    public MencocokkanGambarView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);
        view.setMaxSize(1280, 832);

        // Tambahkan stylesheet
        view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
        view.getStyleClass().add("root");

        setupLayout();
    }

    private void setupLayout() {
        // Set background beige
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area dengan scroll
            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752); // 832 - 80 (navbar)
            scrollPane.setMaxSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            // Content container
            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);

            mainContainer.setCenter(scrollPane);

            // Stack background dan main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");
            System.err.println("Gagal memuat dot background: " + e.getMessage());
        }
    }

    private VBox createContentContainer() {
        VBox container = new VBox(30);
        container.setAlignment(Pos.TOP_CENTER);
        container.setPadding(new Insets(40, 50, 40, 50));
        container.setStyle("-fx-background-color: transparent;");
        container.setMinHeight(700); // Minimum height untuk scroll

        // Header dengan gambar "Cocokkan Gambar"
        VBox headerSection = new VBox(20);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView headerImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan Gambar.png")));
            headerImage.setFitHeight(60);
            headerImage.setPreserveRatio(true);
            headerSection.getChildren().add(headerImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Mencocokkan Gambar");
            headerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 28px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            headerSection.getChildren().add(headerLabel);
        }

        // Instruksi
        Label instruksiLabel = new Label("Hubungkan gambar dengan jawaban yang tepat dengan menarik garis dari titik ke titik");
        instruksiLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-text-fill: #1A1E2C; -fx-text-alignment: center;");
        instruksiLabel.setWrapText(true);
        instruksiLabel.setMaxWidth(600);
        headerSection.getChildren().add(instruksiLabel);

        container.getChildren().add(headerSection);
        return container;
    }

    public void setupMatchingGame(List<String> imagePaths, List<String> answerTexts, List<String> imageIds, List<String> correctAnswerIds) {
        this.imagePaths = imagePaths;
        this.answerTexts = answerTexts;
        this.imageIds = imageIds;
        this.correctAnswerIds = correctAnswerIds;

        // Clear previous connections
        connections.clear();
        imageButtons.clear();
        answerButtons.clear();
        connectionLines.clear();

        // Get content container
        VBox contentContainer = (VBox) ((ScrollPane) ((BorderPane) ((StackPane) view.getCenter()).getChildren().get(1)).getCenter()).getContent();

        // Clear previous game content (keep header)
        if (contentContainer.getChildren().size() > 1) {
            contentContainer.getChildren().subList(1, contentContainer.getChildren().size()).clear();
        }

        // Game area dengan line container
        StackPane gameArea = new StackPane();
        gameArea.setPrefHeight(500);
        gameArea.setMaxHeight(500);

        // Line container untuk menggambar garis
        lineContainer = new Pane();
        lineContainer.setPrefSize(1180, 500);
        lineContainer.setStyle("-fx-background-color: transparent;");

        // Main game layout
        HBox gameLayout = new HBox(200); // Increase spacing for better line drawing
        gameLayout.setAlignment(Pos.CENTER);
        gameLayout.setPadding(new Insets(50));

        // Left side - Images
        VBox imageColumn = createImageColumn();

        // Right side - Answers
        VBox answerColumn = createAnswerColumn();

        gameLayout.getChildren().addAll(imageColumn, answerColumn);

        gameArea.getChildren().addAll(gameLayout, lineContainer); // lineContainer on top for proper rendering

        contentContainer.getChildren().add(gameArea);

        // Action buttons
        HBox buttonSection = new HBox(30);
        buttonSection.setAlignment(Pos.CENTER);
        buttonSection.setPadding(new Insets(30, 0, 0, 0));

        Button selesaiButton = new Button("Selesai");
        selesaiButton.setPrefSize(150, 50);
        selesaiButton.setStyle("-fx-background-color: #516BB0; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 15;");
        selesaiButton.setOnAction(e -> checkAnswers());

        kembaliButton = new Button();
        try {
            ImageView backIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Back.png")));
            backIcon.setFitWidth(40);
            backIcon.setFitHeight(40);
            backIcon.setPreserveRatio(true);
            kembaliButton.setGraphic(backIcon);
        } catch (Exception e) {
            kembaliButton.setText("Kembali");
        }
        kembaliButton.setStyle("-fx-background-color: transparent; -fx-border-width: 0; -fx-padding: 10;");

        buttonSection.getChildren().addAll(kembaliButton, selesaiButton);
        contentContainer.getChildren().add(buttonSection);
    }

    private VBox createImageColumn() {
        VBox imageColumn = new VBox(30);
        imageColumn.setAlignment(Pos.CENTER_LEFT);
        imageColumn.setPrefWidth(400);

        Label imageTitle = new Label("Gambar");
        imageTitle.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 20px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
        imageColumn.getChildren().add(imageTitle);

        for (int i = 0; i < imagePaths.size(); i++) {
            HBox imageRow = createImageRow(imagePaths.get(i), imageIds.get(i));
            imageColumn.getChildren().add(imageRow);
        }

        return imageColumn;
    }

    private HBox createImageRow(String imagePath, String imageId) {
        HBox row = new HBox(15);
        row.setAlignment(Pos.CENTER_LEFT);

        // Image container
        VBox imageContainer = new VBox();
        imageContainer.setAlignment(Pos.CENTER);
        imageContainer.setPrefSize(150, 100);
        imageContainer.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.2), 8, 0, 0, 3);");

        try {
            ImageView imageView = new ImageView(new Image(getClass().getResourceAsStream(imagePath)));
            imageView.setFitWidth(130);
            imageView.setFitHeight(80);
            imageView.setPreserveRatio(true);
            imageContainer.getChildren().add(imageView);
        } catch (Exception e) {
            Label placeholder = new Label("Gambar");
            placeholder.setStyle("-fx-font-size: 14px; -fx-text-fill: #666;");
            imageContainer.getChildren().add(placeholder);
        }

        // Connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(20, 20);
        connectPoint.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(16);
            dotIcon.setFitHeight(16);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            connectPoint.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> startConnection(imageId, connectPoint));

        imageButtons.put(imageId, connectPoint);
        row.getChildren().addAll(imageContainer, connectPoint);
        return row;
    }

    private VBox createAnswerColumn() {
        VBox answerColumn = new VBox(30);
        answerColumn.setAlignment(Pos.CENTER_RIGHT);
        answerColumn.setPrefWidth(400);

        Label answerTitle = new Label("Jawaban");
        answerTitle.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 20px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
        answerColumn.getChildren().add(answerTitle);

        for (int i = 0; i < answerTexts.size(); i++) {
            HBox answerRow = createAnswerRow(answerTexts.get(i), imageIds.get(i));
            answerColumn.getChildren().add(answerRow);
        }

        return answerColumn;
    }

    private HBox createAnswerRow(String answerText, String answerId) {
        HBox row = new HBox(15);
        row.setAlignment(Pos.CENTER_RIGHT);

        // Connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(20, 20);
        connectPoint.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(16);
            dotIcon.setFitHeight(16);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            connectPoint.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> completeConnection(answerId, connectPoint));

        // Answer container
        VBox answerContainer = new VBox();
        answerContainer.setAlignment(Pos.CENTER);
        answerContainer.setPrefSize(150, 100);
        answerContainer.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.2), 8, 0, 0, 3);");

        Label answerLabel = new Label(answerText);
        answerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-text-fill: #1A1E2C; -fx-text-alignment: center;");
        answerLabel.setWrapText(true);
        answerLabel.setMaxWidth(130);
        answerContainer.getChildren().add(answerLabel);

        answerButtons.put(answerId, connectPoint);
        row.getChildren().addAll(connectPoint, answerContainer);
        return row;
    }

    private void startConnection(String imageId, Button imageButton) {
        // Clear previous selection
        resetAllButtonStyles();

        selectedImageId = imageId;

        // Visual feedback - highlight selected image point
        imageButton.setStyle("-fx-background-color: #2ecc71; -fx-background-radius: 10; -fx-border-width: 0;");

        // If there was a previous connection from this image, highlight the connected answer
        String connectedAnswerId = connections.get(imageId);
        if (connectedAnswerId != null) {
            Button answerButton = answerButtons.get(connectedAnswerId);
            answerButton.setStyle("-fx-background-color: #e74c3c; -fx-background-radius: 10; -fx-border-width: 0;");
        }
    }

    private void completeConnection(String answerId, Button answerButton) {
        if (selectedImageId != null) {
            // Remove old connection if exists
            String oldAnswer = connections.get(selectedImageId);
            if (oldAnswer != null) {
                Line oldLine = connectionLines.get(selectedImageId);
                if (oldLine != null) {
                    lineContainer.getChildren().remove(oldLine);
                }
            }

            // Create new connection
            Button imageButton = imageButtons.get(selectedImageId);
            Line line = createConnectionLine(imageButton, answerButton);

            lineContainer.getChildren().add(line);
            connections.put(selectedImageId, answerId);
            connectionLines.put(selectedImageId, line);

            // Reset visual feedback
            resetAllButtonStyles();
            selectedImageId = null;
        }
    }

    private Line createConnectionLine(Button startButton, Button endButton) {
        Line line = new Line();

        // Calculate positions based on scene coordinates
        double startX = startButton.getLayoutX() + startButton.getWidth() / 2;
        double startY = startButton.getLayoutY() + startButton.getHeight() / 2;
        double endX = endButton.getLayoutX() + endButton.getWidth() / 2;
        double endY = endButton.getLayoutY() + endButton.getHeight() / 2;

        // Adjust for the game layout positioning
        line.setStartX(startX + 50); // Adjust for padding
        line.setStartY(startY + 50);
        line.setEndX(endX + 50);
        line.setEndY(endY + 50);

        line.setStroke(Color.web("#516BB0"));
        line.setStrokeWidth(3);
        line.setOpacity(0.8);

        return line;
    }

    private void resetAllButtonStyles() {
        // Reset image buttons
        for (Button button : imageButtons.values()) {
            button.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        // Reset answer buttons
        for (Button button : answerButtons.values()) {
            button.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");
        }
    }

    private void checkAnswers() {
        int correctAnswers = 0;

        // Count correct answers
        for (int i = 0; i < imageIds.size(); i++) {
            String imageId = imageIds.get(i);
            String userAnswer = connections.get(imageId);
            String correctAnswer = correctAnswerIds.get(i);

            if (userAnswer != null && userAnswer.equals(correctAnswer)) {
                correctAnswers++;
            }
        }

        // Trigger callback with results
        if (onGameComplete != null) {
            onGameComplete.onGameComplete(correctAnswers, imageIds.size());
        }
    }

    /**
     * Membuat navbar seperti halaman lain
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
