    }

    /**
     * Method untuk menghentikan audio yang sedang diputar
     * Diperbaiki untuk menghentikan audio segera tanpa delay
     */
    public void stopAudio() {
        try {
            if (mediaPlayer != null) {
                // Stop audio regardless of status - lebih agresif
                MediaPlayer.Status status = mediaPlayer.getStatus();
                if (status == MediaPlayer.Status.PLAYING ||
                        status == MediaPlayer.Status.PAUSED ||
                        status == MediaPlayer.Status.READY) {

                    // Force immediate stop
                    mediaPlayer.stop();
                    System.out.println("Audio IMMEDIATELY stopped for page change (was: " + status + ")");
                } else {
                    System.out.println("Audio already stopped or not ready (status: " + status + ")");
                }

                // Force dispose untuk memastikan resource dilepas segera
                mediaPlayer.dispose();
                mediaPlayer = null;
            }
            isSoundOn = false;
            updateVolumeIcon();
        } catch (Exception e) {
            System.err.println("Error stopping audio: " + e.getMessage());
            // Paksa reset MediaPlayer meski ada error
            try {
                if (mediaPlayer != null) {
                    mediaPlayer.dispose();
                    mediaPlayer = null;
                }
            } catch (Exception disposeEx) {
                System.err.println("Error disposing MediaPlayer: " + disposeEx.getMessage());
            }
            isSoundOn = false;
        }
    }

    /**
     * Method yang dipanggil ketika view akan disembunyikan atau tidak aktif
     */
    public void onViewDeactivated() {
        stopAudio();
        System.out.println("PenjelasanView deactivated - audio stopped");
    }

    /**
     * Method yang dipanggil ketika view akan ditampilkan atau aktif
     */
    public void onViewActivated() {
        // Reset audio state ketika view aktif kembali
        isSoundOn = false;
        updateVolumeIcon();
        System.out.println("PenjelasanView activated");
    }

    /**
     * Method untuk cleanup MediaPlayer ketika view tidak digunakan lagi
     * Diperbaiki untuk cleanup yang lebih agresif
     */
    public void cleanup() {
        try {
            // Stop audio dulu sebelum cleanup dengan method yang sudah diperbaiki
            stopAudio();

            // Double check cleanup
            if (mediaPlayer != null) {
                try {
                    mediaPlayer.stop();
                    mediaPlayer.dispose();
                } catch (Exception disposeEx) {
                    System.err.println("Error disposing during cleanup: " + disposeEx.getMessage());
                }
                mediaPlayer = null;
                System.out.println("MediaPlayer aggressively cleaned up");
            }
            isSoundOn = false;
        } catch (Exception e) {
            System.err.println("Error during cleanup: " + e.getMessage());
            // Force reset even with errors
            mediaPlayer = null;
            isSoundOn = false;
        }
    }
}

