    public void displayTeknik(Teknik teknik) {
        // Stop audio dari teknik sebelumnya jika ada
        stopAudio();

        // Simpan nama teknik saat ini untuk audio
        currentTeknikName = teknik.getNama().toLowerCase();

        // Set title image berdasarkan teknik
        try {
            String titlePath = "/images/" + teknik.getNama() + "_title.png";
            try {
                Image titleImage = new Image(getClass().getResourceAsStream(titlePath));
                titleImageView.setImage(titleImage);
            } catch (Exception titleEx) {
                // Fallback ke teks jika gambar title tidak ada
                titleImageView.setImage(null);
            }
        } catch (Exception e) {
            titleImageView.setImage(null);
        }

        // Set gambar pengertian (pengertian_*.png)
        try {
            String imagePath = "/images/pengertian_" + teknik.getNama().toLowerCase() + ".png";
            Image image = new Image(getClass().getResourceAsStream(imagePath));
            teknikImageView.setImage(image);
        } catch (Exception e) {
            System.err.println("Error loading explanation image for " + teknik.getNama() + ": " + e.getMessage());
            // Fallback jika gambar tidak ditemukan
            teknikImageView.setImage(null);
        }

        // Set gambar teknik (badminton_*.jpg atau soccer_*.jpg) menggunakan class field
        try {
            String techniqueImagePath = "";
            String teknikName = teknik.getNama().toLowerCase();

            // Mapping untuk gambar teknik yang sesuai
            switch (teknikName) {
                // Badminton techniques
                case "smash":
                    techniqueImagePath = "/images/badminton_smash.jpg";
                    break;
                case "netting":
                    techniqueImagePath = "/images/badminton_netting.jpg";
                    break;
                case "servis":
                    techniqueImagePath = "/images/badminton_service.jpg";
                    break;
                case "footwork":
                    techniqueImagePath = "/images/badminton_footwork.jpg"; // Gambar baru
                    break;
                // Soccer techniques
                case "dribbling":
                    techniqueImagePath = "/images/soccer_dribble.jpg";
                    break;
                case "shooting":
                    techniqueImagePath = "/images/soccer_shoot.jpg";
                    break;
                case "heading":
                    techniqueImagePath = "/images/soccer_heading.jpg";
                    break;
                case "passing":
                    techniqueImagePath = "/images/soccer_passing.jpg"; // Gambar baru
                    break;
                default:
                    System.out.println("No specific technique image found for: " + teknikName);
                    break;
            }

            if (!techniqueImagePath.isEmpty()) {
                Image techniqueImage = new Image(getClass().getResourceAsStream(techniqueImagePath));
                techniquePhotoView.setImage(techniqueImage);
            } else {
                techniquePhotoView.setImage(null);
            }
        } catch (Exception e) {
            System.err.println("Error loading technique photo for " + teknik.getNama() + ": " + e.getMessage());
            techniquePhotoView.setImage(null);
        }

        // Set deskripsi
        descriptionLabel.setText(teknik.getDeskripsi());
    }

    private void toggleSound() {
        try {
            if (mediaPlayer != null && mediaPlayer.getStatus() == MediaPlayer.Status.PLAYING) {
                // Jika audio sedang diputar, stop audio menggunakan method yang sudah
                // diperbaiki
                stopAudio();
                System.out.println("Audio stopped via volume button");
            } else {
                // Jika audio tidak diputar, putar audio sesuai teknik saat ini
                playAudioForCurrentTeknik();
            }
        } catch (Exception e) {
            System.err.println("Error toggling sound: " + e.getMessage());
            // Force stop audio meski ada error
            stopAudio();
        }
    }

    private void playAudioForCurrentTeknik() {
        try {
            // Force stop dan cleanup audio sebelumnya dengan cara yang lebih agresif
            if (mediaPlayer != null) {
                try {
                    mediaPlayer.stop();
                    mediaPlayer.dispose();
                } catch (Exception cleanupEx) {
                    System.err.println("Error during cleanup: " + cleanupEx.getMessage());
                }
                mediaPlayer = null;
            }

            // Gunakan audio sesuai dengan teknik saat ini
            String audioPath = "/audio/" + currentTeknikName + ".mp3";

            System.out.println("Looking for audio: " + audioPath + " (current technique: " + currentTeknikName + ")");

            // Coba beberapa cara untuk mendapatkan resource
            var audioURL = getClass().getResource(audioPath);

            if (audioURL == null) {
                // Coba cara lain dengan ClassLoader
                String altPath = "audio/" + currentTeknikName + ".mp3";
                audioURL = getClass().getClassLoader().getResource(altPath);
                System.out.println("Trying alternative path: " + altPath);
            }

            if (audioURL == null) {
                // Coba berbagai cara dinamis untuk menemukan audio file
                try {
                    // 1. Coba dari working directory saat ini (untuk portable distribution)
                    String workingDir = System.getProperty("user.dir");
                    System.out.println("DEBUG: Current working directory: " + workingDir);

                    String[] relativePaths = {
                        // Untuk development (project asli)
                        "src/main/resources/audio/" + currentTeknikName + ".mp3",
                        "target/classes/audio/" + currentTeknikName + ".mp3",

                        // Untuk portable distribution (running from sportedu folder)
                        "src/main/resources/audio/" + currentTeknikName + ".mp3",
                        "target/classes/audio/" + currentTeknikName + ".mp3",

                        // Fallback paths
                        "audio/" + currentTeknikName + ".mp3",
                        "../audio/" + currentTeknikName + ".mp3"
                    };

                    for (String relativePath : relativePaths) {
                        java.io.File audioFile = new java.io.File(workingDir, relativePath);
                        System.out.println("DEBUG: Checking path: " + audioFile.getAbsolutePath());
                        if (audioFile.exists()) {
                            audioURL = audioFile.toURI().toURL();
                            System.out.println("SUCCESS: Found audio at: " + audioFile.getAbsolutePath());
                            break;
                        }
                    }

                    // 2. Jika belum ketemu, compile/build dulu untuk generate target/classes
                    if (audioURL == null) {
                        System.out.println("DEBUG: Audio not found, checking if target/classes exists...");
                        java.io.File targetClasses = new java.io.File(workingDir, "target/classes/audio");
                        if (!targetClasses.exists()) {
                            System.out.println("INFO: target/classes/audio not found. Application needs to be compiled first.");
                            System.out.println("INFO: Maven will compile automatically on first run.");
                        }

                        // Coba lagi setelah info
                        java.io.File audioFile = new java.io.File(workingDir, "target/classes/audio/" + currentTeknikName + ".mp3");
                        if (audioFile.exists()) {
                            audioURL = audioFile.toURI().toURL();
                            System.out.println("SUCCESS: Found audio in target/classes: " + audioFile.getAbsolutePath());
                        }
                    }

                    // 3. Debug info - list available files
                    if (audioURL == null) {
                        System.out.println("DEBUG: Listing available directories and files...");

                        // Check src/main/resources/audio
                        java.io.File srcAudioDir = new java.io.File(workingDir, "src/main/resources/audio");
                        if (srcAudioDir.exists()) {
                            System.out.println("DEBUG: src/main/resources/audio exists");
                            java.io.File[] mp3Files = srcAudioDir.listFiles((dir, name) -> name.endsWith(".mp3"));
                            if (mp3Files != null && mp3Files.length > 0) {
                                System.out.println("DEBUG: Available MP3 files in src/main/resources/audio:");
                                for (java.io.File mp3 : mp3Files) {
                                    System.out.println("  - " + mp3.getName());
                                }
                            }
                        } else {
                            System.out.println("DEBUG: src/main/resources/audio does NOT exist");
                        }

                        // Check target/classes/audio
                        java.io.File targetAudioDir = new java.io.File(workingDir, "target/classes/audio");
                        if (targetAudioDir.exists()) {
                            System.out.println("DEBUG: target/classes/audio exists");
                            java.io.File[] mp3Files = targetAudioDir.listFiles((dir, name) -> name.endsWith(".mp3"));
                            if (mp3Files != null && mp3Files.length > 0) {
                                System.out.println("DEBUG: Available MP3 files in target/classes/audio:");
                                for (java.io.File mp3 : mp3Files) {
                                    System.out.println("  - " + mp3.getName());
                                }
                            }
                        } else {
                            System.out.println("DEBUG: target/classes/audio does NOT exist - Maven compilation needed");
                        }
                    }

                } catch (Exception fileEx) {
                    System.err.println("Dynamic file search failed: " + fileEx.getMessage());
                    fileEx.printStackTrace();
                }
            }

            if (audioURL != null) {
                System.out.println("SUCCESS: Audio file found at: " + audioURL.toExternalForm());
                Media media = new Media(audioURL.toExternalForm());
                mediaPlayer = new MediaPlayer(media);

                mediaPlayer.setOnReady(() -> {
                    System.out.println("MediaPlayer ready, starting playback for: " + currentTeknikName);
                    mediaPlayer.play();
                    isSoundOn = true;
                    updateVolumeIcon();
                });

                mediaPlayer.setOnEndOfMedia(() -> {
                    System.out.println("Audio finished playing: " + currentTeknikName);
                    isSoundOn = false;
                    updateVolumeIcon();
                });

                mediaPlayer.setOnError(() -> {
                    System.err.println("Error playing audio: " + mediaPlayer.getError());
                    isSoundOn = false;
                    updateVolumeIcon();
                });

            } else {
                System.err.println("FAILED: Audio file not found for technique: " + currentTeknikName);
                System.err.println("Expected file: " + audioPath);
                // List available audio files for debugging
                try {
                    var audioDir = getClass().getResource("/audio");
                    if (audioDir != null) {
                        System.out.println("Audio directory found: " + audioDir);
                    } else {
                        System.err.println("Audio directory not found: /audio/");
                    }
                } catch (Exception debugEx) {
                    System.err.println("Debug error: " + debugEx.getMessage());
                }
            }
        } catch (Exception e) {
            System.err.println("Error playing audio for " + currentTeknikName + ": " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void updateVolumeIcon() {
        try {
            String volumeImagePath = isSoundOn ? "/images/volume on.png" : "/images/volume off.png";
            ImageView volumeImageView = new ImageView(new Image(getClass().getResourceAsStream(volumeImagePath)));
            volumeImageView.setFitWidth(50);
            volumeImageView.setFitHeight(50);
            volumeImageView.setPreserveRatio(true);
            speakerButton.setGraphic(volumeImageView);
        } catch (Exception e) {
            System.err.println("Error loading volume icon: " + e.getMessage());
        }
    }

    public Parent getView() {
        return view;
    }

    public Button getBackButton() {
        return backButton;
    }

    public Button getNextButton() {
        return nextButton;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }

    /**
     * Method untuk menghentikan audio yang sedang diputar
     * Diperbaiki untuk menghentikan audio segera tanpa delay
     */
    public void stopAudio() {
        try {
            if (mediaPlayer != null) {
                // Stop audio regardless of status - lebih agresif
                MediaPlayer.Status status = mediaPlayer.getStatus();
                if (status == MediaPlayer.Status.PLAYING ||
                        status == MediaPlayer.Status.PAUSED ||
                        status == MediaPlayer.Status.READY) {

                    // Force immediate stop
                    mediaPlayer.stop();
                    System.out.println("Audio IMMEDIATELY stopped for page change (was: " + status + ")");
                } else {
                    System.out.println("Audio already stopped or not ready (status: " + status + ")");
                }

                // Force dispose untuk memastikan resource dilepas segera
                mediaPlayer.dispose();
                mediaPlayer = null;
            }
            isSoundOn = false;
            updateVolumeIcon();
        } catch (Exception e) {
            System.err.println("Error stopping audio: " + e.getMessage());
            // Paksa reset MediaPlayer meski ada error
            try {
                if (mediaPlayer != null) {
                    mediaPlayer.dispose();
                    mediaPlayer = null;
                }
            } catch (Exception disposeEx) {
                System.err.println("Error disposing MediaPlayer: " + disposeEx.getMessage());
            }
            isSoundOn = false;
        }
    }

    /**
     * Method yang dipanggil ketika view akan disembunyikan atau tidak aktif
     */
    public void onViewDeactivated() {
        stopAudio();
        System.out.println("PenjelasanView deactivated - audio stopped");
    }

    /**
     * Method yang dipanggil ketika view akan ditampilkan atau aktif
     */
    public void onViewActivated() {
        // Reset audio state ketika view aktif kembali
        isSoundOn = false;
        updateVolumeIcon();
        System.out.println("PenjelasanView activated");
    }

    /**
     * Method untuk cleanup MediaPlayer ketika view tidak digunakan lagi
     * Diperbaiki untuk cleanup yang lebih agresif
     */
    public void cleanup() {
        try {
            // Stop audio dulu sebelum cleanup dengan method yang sudah diperbaiki
            stopAudio();

            // Double check cleanup
            if (mediaPlayer != null) {
                try {
                    mediaPlayer.stop();
                    mediaPlayer.dispose();
                } catch (Exception disposeEx) {
                    System.err.println("Error disposing during cleanup: " + disposeEx.getMessage());
                }
                mediaPlayer = null;
                System.out.println("MediaPlayer aggressively cleaned up");
            }
            isSoundOn = false;
        } catch (Exception e) {
            System.err.println("Error during cleanup: " + e.getMessage());
            // Force reset even with errors
            mediaPlayer = null;
            isSoundOn = false;
        }
    }
}

package com.sportedu.view;

import com.sportedu.model.Soal;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;

/**
 * View untuk menampilkan gameplay kuis Tebak Gambar dengan desain sesuai tampilan 2.1
 * Menggunakan navbar, dot background, dan layout yang proper
 */
public class QuizView {

    private final BorderPane view;
    private final Button kembaliButton;
    public Button[] pilihanButtons;

    // Navbar buttons - akan di-set dari MainView
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    public QuizView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);

        kembaliButton = UIFactory.createNavButton("/images/Back.png", 120, 50);
        setupLayout();
    }

    private void setupLayout() {
        // Background dengan dot pattern sesuai desain
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Overlay container untuk konten
            BorderPane overlayContainer = new BorderPane();
            overlayContainer.setPrefSize(1280, 832);
            overlayContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas - sama seperti halaman lain
            HBox navbar = createNavbar();
            overlayContainer.setTop(navbar);

            // Stack background dan overlay
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, overlayContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback jika background tidak ditemukan
            view.setStyle("-fx-background-color: #F5E6A3;");
        }
    }

    /**
     * Membuat navbar yang sama seperti di halaman lain
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    public void displaySoal(Soal soal) {
        // Hapus konten lama dari overlay
        BorderPane overlayContainer = (BorderPane) ((StackPane) view.getCenter()).getChildren().get(1);

        // Content area utama
        VBox contentArea = new VBox(30);
        contentArea.setAlignment(Pos.CENTER);
        contentArea.setPadding(new Insets(40, 80, 40, 80));
        VBox.setVgrow(contentArea, javafx.scene.layout.Priority.ALWAYS);

        // Header dengan logo "Tebak Gambar"
        VBox headerSection = new VBox(20);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView tebakGambarLogo = new ImageView(new Image(getClass().getResourceAsStream("/images/Tebak Gambar.png")));
            tebakGambarLogo.setFitHeight(45);
            tebakGambarLogo.setPreserveRatio(true);
            headerSection.getChildren().add(tebakGambarLogo);
        } catch (Exception e) {
            Label title = new Label("Tebak Gambar");
            title.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 36px; -fx-font-weight: bold; -fx-text-fill: #1A1E2C;");
            headerSection.getChildren().add(title);
        }

        // Gambar soal TERPISAH di atas - dengan background kuning
        VBox gambarContainer = new VBox();
        gambarContainer.setAlignment(Pos.CENTER);
        gambarContainer.setPadding(new Insets(30));
        gambarContainer.setStyle("-fx-background-color: #FFBC4C; -fx-background-radius: 20; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.15), 10, 0, 0, 5);");
        gambarContainer.setMaxWidth(500);

        ImageView gambarSoal = new ImageView();
        try {
            Image image = new Image(getClass().getResourceAsStream(soal.getPertanyaan()));
            if (image.isError()) {
                throw new Exception("Failed to load image: " + soal.getPertanyaan());
            }
            gambarSoal.setImage(image);
        } catch (Exception e) {
            System.err.println("Error loading quiz image: " + soal.getPertanyaan() + " - " + e.getMessage());

            // Fallback: buat placeholder image dengan teks
            gambarSoal.setImage(null);
            gambarSoal.setStyle("-fx-background-color: #E0E0E0; -fx-border-color: #BDBDBD; -fx-border-width: 2; -fx-border-radius: 15;");

            // Tambahkan label untuk menunjukkan gambar tidak ditemukan
            Label errorLabel = new Label("Gambar tidak\nditemukan");
            errorLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-text-fill: #757575; -fx-text-alignment: center;");
            gambarContainer.getChildren().add(errorLabel);
        }
        gambarSoal.setFitHeight(250);
        gambarSoal.setFitWidth(350);
        gambarSoal.setPreserveRatio(true);
        gambarSoal.setStyle("-fx-background-color: white; -fx-border-radius: 15;");

        gambarContainer.getChildren().add(gambarSoal);

        // Container untuk pertanyaan dan jawaban - SATU KOTAK PUTIH
        VBox questionAnswerContainer = new VBox(30);
        questionAnswerContainer.setAlignment(Pos.CENTER);
        questionAnswerContainer.setPadding(new Insets(40));
        questionAnswerContainer.setStyle("-fx-background-color: rgba(255, 255, 255, 0.95); -fx-background-radius: 20; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.15), 10, 0, 0, 5);");
        questionAnswerContainer.setMaxWidth(900);

        // Pertanyaan di dalam kotak putih dengan font biru
        Label pertanyaanLabel = new Label("Apakah nama teknik pada gambar ini?");
        pertanyaanLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 26px; -fx-font-weight: 700; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        pertanyaanLabel.setWrapText(true);

        // Grid untuk pilihan jawaban (2x2) - dengan styling yang sesuai referensi 2.1 (box kuning)
        GridPane pilihanJawabanPane = new GridPane();
        pilihanJawabanPane.setAlignment(Pos.CENTER);
        pilihanJawabanPane.setHgap(30);
        pilihanJawabanPane.setVgap(25);

        pilihanButtons = new Button[4];
        String[] buttonLabels = {"A", "B", "C", "D"};

        for (int i = 0; i < soal.getPilihanJawaban().length; i++) {
            // Format: [A] Jawaban
            String buttonText = "[" + buttonLabels[i] + "] " + soal.getPilihanJawaban()[i];
            pilihanButtons[i] = new Button(buttonText);
            pilihanButtons[i].setPrefSize(350, 70);

            // Styling box kuning sesuai referensi 2.1
            pilihanButtons[i].setStyle(
                "-fx-background-color: #FFBC4C; " +
                "-fx-border-color: #FF9800; " +
                "-fx-border-width: 2; " +
                "-fx-border-radius: 12; " +
                "-fx-background-radius: 12; " +
                "-fx-font-family: 'Poppins', Arial; " +
                "-fx-font-size: 16px; " +
                "-fx-font-weight: 600; " +
                "-fx-text-fill: #1A1E2C; " +
                "-fx-text-alignment: center; " +
                "-fx-effect: dropshadow(gaussian, rgba(255,156,0,0.4), 5, 0, 0, 2);"
            );

            // Hover effects dengan warna kuning lebih gelap
            final Button btn = pilihanButtons[i];
            btn.setOnMouseEntered(e -> btn.setStyle(
                "-fx-background-color: #FF9800; " +
                "-fx-border-color: #F57C00; " +
                "-fx-border-width: 2; " +
                "-fx-border-radius: 12; " +
                "-fx-background-radius: 12; " +
                "-fx-font-family: 'Poppins', Arial; " +
                "-fx-font-size: 16px; " +
                "-fx-font-weight: 700; " +
                "-fx-text-fill: white; " +
                "-fx-text-alignment: center; " +
                "-fx-effect: dropshadow(gaussian, rgba(255,156,0,0.6), 8, 0, 0, 3);"
            ));

            btn.setOnMouseExited(e -> btn.setStyle(
                "-fx-background-color: #FFBC4C; " +
                "-fx-border-color: #FF9800; " +
                "-fx-border-width: 2; " +
                "-fx-border-radius: 12; " +
                "-fx-background-radius: 12; " +
                "-fx-font-family: 'Poppins', Arial; " +
                "-fx-font-size: 16px; " +
                "-fx-font-weight: 600; " +
                "-fx-text-fill: #1A1E2C; " +
                "-fx-text-alignment: center; " +
                "-fx-effect: dropshadow(gaussian, rgba(255,156,0,0.4), 5, 0, 0, 2);"
            ));

            int row = i / 2;
            int col = i % 2;
            pilihanJawabanPane.add(pilihanButtons[i], col, row);
        }

        // Masukkan pertanyaan dan jawaban ke dalam SATU kotak putih
        questionAnswerContainer.getChildren().addAll(pertanyaanLabel, pilihanJawabanPane);

        // Tombol kembali di pojok kiri bawah
        HBox bottomSection = new HBox();
        bottomSection.setAlignment(Pos.BOTTOM_LEFT);
        bottomSection.getChildren().add(kembaliButton);

        // Content area berisi: header, gambar (kotak kuning), pertanyaan+jawaban (kotak putih), tombol kembali
        contentArea.getChildren().addAll(headerSection, gambarContainer, questionAnswerContainer, bottomSection);

        overlayContainer.setCenter(contentArea);
    }

